const CLAUSE_MARK_MASK: u32 = 0b11;
const CLAUSE_LEARNT_BIT: u32 = 1 << 2;
const CLAUSE_HAS_EXTRA_BIT: u32 = 1 << 3;
const CLAUSE_RELOCED_BIT: u32 = 1 << 4;
/// Kissat clause.h `searched` (SAT_SEARCHED, default on): each clause header
/// carries a 6-bit saved replacement-scan position (clamped to 63); the next
/// replacement-watch scan resumes there (wrapping to the 2..pos prefix),
/// amortizing the scan instead of rescanning the falsified prefix from
/// position 2 on every visit. bp4 measured 21.7 scanned lits/propagation =
/// 61% of all search ticks (avg 12.7 lits per loaded clause) with the
/// always-from-2 scan. The field lives in the header word the hot loop loads
/// anyway (and the header's cache line is dirtied by the lits[1] swap on
/// every successful move), so reading/updating it costs no extra cache-line
/// traffic — a trailing-word variant of this port measured a NET wall
/// regression on bp4 (+3.4% clean) from the extra tail-line touch despite a
/// 16% tick cut; do not resurrect it.
const CLAUSE_SEARCHED_POS_SHIFT: u32 = 5;
const CLAUSE_SEARCHED_POS_MAX: u32 = 63;
const CLAUSE_SEARCHED_POS_MASK: u32 = CLAUSE_SEARCHED_POS_MAX << CLAUSE_SEARCHED_POS_SHIFT;
const CLAUSE_SIZE_SHIFT: u32 = 11;
const CLAUSE_DELETED_MARK: u32 = 1;
const DEFAULT_BVE_GROW: isize = 0;
const DEFAULT_BVE_CLAUSE_LIMIT: isize = 20;
const DEFAULT_SUBSUMPTION_LIMIT: isize = 1000;
/// Default conflicts between inprocessing rounds when SAT_INPROCESS_INTERVAL_CONFLICTS=0.
const INPROCESS_DEFAULT_INTERVAL: u64 = 2000;
/// SAT_INPROCESS_TICK_CADENCE defaults. The interval is sized from measured tick rates
/// (2026-07-24, 240 s windows): the starved class runs 4.3M-9.5M ticks/s, so 1.5e9 ticks
/// is roughly 160-350 s of work — about 5-11 rounds across an 1800 s run on cells that
/// currently get ZERO. The ratio floor of 12k ticks/conflict sits in the measured gap
/// between the healthy class (<=9.2k: case7 9012, sqrt170 9155, fixedbandwidth 4362) and
/// the starved class (>=15k: VexRiscv 15033, goldcrest 20925, pj2008 23671, lockchart
/// 47123), so healthy cells never arm the tick trigger and keep their exact trajectory.
const INPROCESS_DEFAULT_TICK_INTERVAL: u64 = 1_500_000_000;
const INPROCESS_DEFAULT_TICKS_PER_CONF_MIN: u64 = 12_000;
/// Minimum conflicts before the ticks/conflict ratio is trusted to classify the formula.
/// Early search is propagation-heavy and unrepresentative, so classifying at conflict 1
/// would arm nearly everything.
const INPROCESS_TICK_RATIO_MIN_CONFLICTS: u64 = 20_000;
/// Endgame cadence (SAT_ENDGAME, default on): LATE-ARMED formulas (see
/// ENDGAME_MIN_ARMED_AT) latch the kissat-parity endgame cadence at arming —
/// flat ENDGAME_REPHASE_DELTA rephase/walk cycle plus the aggressive restart
/// floor/margin (parts "rf"; the pinned-inprocess part 'i' is default-OFF: it
/// was measured both unnecessary for the TT406 flip and the killer of the
/// dense yield-armed refutation cells, slowing sqrt-mitern170 ~40%).
/// Decomposition (2026-07-23, idle, from-arming): TT406 parts=rf SAT 155s /
/// 593k conflicts; parts=r SAT 904s / 3.15M; parts=f timeout — flat rephase
/// carries the flip, the restart floor multiplies it. Original motivation
/// (2026-07-22): kissat 4.0.4 solves SC25_Timetable_C_406 SAT in ~31s/170k
/// conflicts with 18 vivifications + 4 walks + restart interval 23, while the
/// shipped armed cadence wandered 1.48M conflicts in 300s with restart
/// interval 235 on the same cell. Trigger default 1 = latch at arming.
const ENDGAME_TRIGGER_CONFLICTS: u64 = 1;
/// Late-arming scope for the endgame latch (SAT_ENDGAME_MIN_ARMED default):
/// only cells whose arming itself happened at or after this many conflicts
/// latch the endgame. Measured 2026-07-23: instantly-armed cells
/// (`inprocess_armed_at_conflict` == 1: vex/oski15x2/TT492 class) carry banked
/// trajectory lottery wins and lose under any cadence reroll (TT492's SAT draw
/// died in both the unscoped probe and the unscoped-bundle session), while
/// every late-armed cell (TT406/TT395 decision-armed at ~200k; sqrt-miter/QG7/
/// Pancake/aaai10 yield-armed at ~800k) survives or wins under the rf cadence.
/// Gate 2026-07-23 (cand 70 vs base 69): TT406 timeout -> SAT 212s in-gate.
const ENDGAME_MIN_ARMED_AT: u64 = 100_000;
/// Pinned conflicts between inprocess rounds while the endgame is active
/// (kissat's measured vivification interval on TT406 is ~9.5k).
const ENDGAME_INPROCESS_INTERVAL: u64 = 10_000;
/// Flat rephase interval while the endgame is active (replaces the n·log3(n)
/// growth; kissat walked TT406 every ~42k conflicts).
const ENDGAME_REPHASE_DELTA: u64 = 50_000;
/// Flat endgame rephase cycle for DECISION-ARMED cells (armed before
/// ENDGAME_DELTA_ARMED_SPLIT; the SC25 Timetable class arms at ~200k).
/// The yield-armed (~800k) classes always keep ENDGAME_REPHASE_DELTA so
/// their banked trajectories stay bit-identical.
/// 48_000 promoted 2026-07-23 (gate WIN 70v68): SC25_Timetable_C_496
/// first-ever solve (1097s in-gate / 2.57M conflicts; kissat 4.0.4 times
/// out at 1800s), TT395 393k (-254k), TT406 909k (+316k, 290s in-gate).
/// Only 48k (and uselessly-thin 49k) flips TT496 across 12 tested deltas.
const ENDGAME_REPHASE_DELTA_DEC: u64 = 48_000;
/// Arming-time split separating decision-armed (~200k) from yield-armed
/// (~800k) endgame cells.
const ENDGAME_DELTA_ARMED_SPLIT: u64 = 500_000;
/// Focused restart-interval floor while the endgame is active (kissat's measured
/// TT406 restart interval is 23; the shipped EMA floor is 50 plus log growth).
const ENDGAME_RESTART_FLOOR: u64 = 10;
/// Fast/slow LBD-EMA restart margin while the endgame is active (shipped: 1.20).
const ENDGAME_RESTART_MARGIN: f64 = 1.05;
/// Conflicts between unarmed flywheel eliminate rounds (SAT_ELIM_UNARMED_FLYWHEEL).
/// Kissat re-eliminates every ~500·n·log²n conflicts (eliminateint=500 with the
/// NLOG2N conflict-limit update) — dozens of rounds per million conflicts; 100k is
/// the conservative port that still yields ~10 escalating rounds in the 1M→2M
/// window where the g2-class clause collapse has to happen.
const UNARMED_FLYWHEEL_INTERVAL: u64 = 100_000;
/// Density-class guard for the unarmed flywheel: formulas at or below this
/// decisions-per-conflict ratio are the yield-arm candidates (QG7/Pancake class)
/// where complete-round escalation measured toxic; leave them on the shipped path.
const UNARMED_FLYWHEEL_MIN_DEC_PER_CONF: u64 = 3;
/// Minimum fraction of clauses that must be consumed by extracted XOR constraints
/// before the XOR/parity Gaussian engine (SAT_GAUSS) attempts a refutation. Below
/// this the formula is not parity-structured, so a Gaussian pass would be a costly
/// no-op; Tseitin instances sit at ~1.0 while incidental-XOR formulas sit well below.
const GAUSS_MIN_COVERAGE: f64 = 0.90;
/// Upper bound on original-clause count for the XOR extraction pass (default-on
/// safety): above this the one-shot extraction allocation/time is not worth paying
/// on every solve. A pure viability bound (no profile20 cell approaches it); larger
/// parity instances can still opt in via SAT_GAUSS with this raised.
const GAUSS_MAX_CLAUSES: usize = 5_000_000;
/// Upper bound on original-clause count for gate congruence closure (SAT_CONGRUENCE):
/// above this the occurrence-index allocation is not worth paying. Circuit miters sit
/// well under this (VexRiscv ~2.3M clauses).
const CONGRUENCE_MAX_CLAUSES: usize = 40_000_000;
/// Maximum congruence→substitute rounds before giving up on the fixpoint. Each round that
/// finds a merge strictly reduces the active-variable count, so this only caps pathology.
const CONGRUENCE_MAX_ROUNDS: usize = 64;
/// Clauses longer than this are ignored as gate bases during congruence extraction (gate
/// definitions in circuit miters are small; the O(size^2) base scan must stay bounded).
const CONGRUENCE_MAX_CLAUSE_LEN: usize = 64;
/// Maximum XOR-relation arity (total variables, including the chosen output) considered by
/// gate congruence when `SAT_CONGRUENCE_XOR` is on. An arity-`k` relation is defined by
/// `2^(k-1)` clauses of length `k`, and each merge over it emits `2^k - 4` RUP proof-chain
/// helpers, so this bound keeps both detection and proof size in check. Circuit XORs are
/// dominated by `k = 3` (2-input XOR gates) and `k = 4` (adder sum/carry bits).
const CONGRUENCE_MAX_XOR_ARITY: usize = 4;
/// Maximum congruence↔BVE outer iterations at the root when `SAT_CONGRUENCE_ITER` is on.
/// Each iteration runs a full gate-congruence closure (ELS-substituting the merges) then a
/// BVE round; the BVE round unifies gate inputs so the next closure can find congruent
/// AND/XOR gates that were invisible before substitution. Mirrors kissat's ~14-closure
/// congruence/BVE interleave (`congruence.c`); capped so a pathological formula cannot spin.
const CONGRUENCE_ITER_MAX_ROUNDS: usize = 20;
/// Wall-clock budget (seconds) for the entire congruence↔BVE root fixpoint. The loop stops
/// early once this is exceeded so the root reduction cannot eat the whole solve budget on a
/// large miter (C.1's single congruence pass alone was ~34s on VexRiscv). Search then
/// proceeds on whatever reduction was achieved.
const CONGRUENCE_ITER_MAX_SECONDS: f64 = 300.0;
/// Default per-round vivification budget as a fraction (per mille) of cumulative
/// search propagations. Inprocessing then scales as a small bounded share of the
/// search effort already spent, rather than as a static multiple of formula size.
/// Kept deliberately small (2%): measured inert on easy profile20 instances (the
/// 5M floor dominates there — mp1/SCPC byte-for-byte identical at 10/100/1000 per
/// mille), and on billion-propagation instances 100 per mille pinned every late
/// round at the 100M ceiling (vivify-on then dominated wall time). 20 per mille
/// caps a 1e9-propagation round near 20M ticks instead. The exact value is a
/// seedgate-tuning knob (`SAT_VIVIFY_PERMILLE`); this is a conservative default.
const DEFAULT_VIVIFY_PERMILLE: u64 = 20;
/// Floor/ceiling on the per-round vivification propagation budget. The floor keeps
/// early rounds (few propagations spent so far) from starving; the ceiling bounds
/// the work a single root visit can do on long runs.
const VIVIFY_BUDGET_MIN_TICKS: u64 = 5_000_000;
const VIVIFY_BUDGET_MAX_TICKS: u64 = 100_000_000;
/// Default cap on original-clause length considered for vivification.
const DEFAULT_VIVIFY_MAX_CLAUSE_LEN: usize = 100;
/// Bead SAT-playground-5b2.3.6: after this many consecutive vivify rounds that
/// strengthen nothing and derive no unit, stop scheduling vivify for the instance.
const VIVIFY_MAX_UNPRODUCTIVE_ROUNDS: u32 = 2;
/// Bead SAT-playground-5b2.3.38.1: consecutive zero-yield COMPLETED sweep passes after
/// which sweeping is retired for the instance (kissat's `BUMP_DELAY(sweep)` analogue).
/// Only consulted in `SAT_SWEEP_SCHED=retire` mode.
const SWEEP_MAX_UNPRODUCTIVE_PASSES: u32 = 2;
/// Learned-clause vivification is useful only once search has already spent a
/// very large budget. Delaying it keeps the promoted 1M sweep cadence intact
/// while skipping fragile long SAT cells that finish before 6M conflicts.
const DEFAULT_LEARNED_VIVIFY_DELAY_CONFLICTS: u64 = 6_000_000;
/// On binary-dominated formulas, learned-clause vivification can churn the low-LBD
/// implication graph enough to derail SAT trajectories. Keep original-clause
/// vivification, but leave learnt candidates out once the post-preprocess formula is
/// at least as binary-heavy as the inblock shrink gate.
const LEARNED_VIVIFY_BINARY_DOMINATED_FRACTION: f64 = 0.85;
/// Bead SAT-playground-5b2.3.6: when learnt-clause vivification is on, only vivify
/// LEARNT clauses with stored LBD at or below this (tier1/tier2). Vivifying all learnt
/// clauses (measured 74k on SCPC) churns the learnt DB and inflates conflicts; kissat
/// restricts to the low-glue tiers where the value is and the churn is small.
const VIVIFY_LEARNED_MAX_LBD: u16 = 6;
/// Bead SAT-playground-5b2.3.38: max variables swept per sweeping round.
const SWEEP_SEED_BUDGET: usize = 512;
/// Bead SAT-playground-5b2.3.38: max kitten solve calls per environment.
const SWEEP_SOLVE_BUDGET: usize = 2000;
/// Bead SAT-playground-5b2.3.38.1 (kissat `sweep.c` parity): escalation caps applied
/// once a full seed pass completes. kissat doubles the environment variable/clause
/// bounds and increments depth per completed sweep (`sweepmaxvars`, `sweepmaxclauses`,
/// `sweepmaxdepth`); our per-round bases (`SWEEP_MAX_VARS` 256, `SWEEP_MAX_CLAUSES`
/// 1024, `SWEEP_DEPTH` 2) already match kissat's initial values, so only the ladder was
/// missing. Without it a formula whose equivalences sit outside a depth-2/256-var
/// neighborhood can never be reached no matter how many rounds run.
const SWEEP_MAX_VARS_CAP: usize = 8192;
const SWEEP_MAX_CLAUSES_CAP: usize = 32768;
const SWEEP_MAX_DEPTH_CAP: usize = 3;
/// SAT_SWEEP_ROOT: root sweep pass (kissat-productivity SAT sweeping BEFORE search).
/// The pass-1 scan is a pure dry-run: facts and their kitten proofs are buffered and
/// nothing is emitted or applied unless the found mass (units + equivalences) crosses
/// `SAT_SWEEP_ROOT_MIN_FOUND_PERMILLE` of the live variables — the all-or-nothing
/// scoping shape shared with congruence/transitive/scoped-gate-BVE, so below-threshold
/// formulas keep byte-identical trajectories. On adoption the pass loops full seed
/// sweeps with the kissat escalation ladder until the kitten-tick budget is spent or
/// two consecutive completed passes prove nothing.
const SWEEP_ROOT_BUDGET_LITS_MULTIPLIER: u64 = 200;
const SWEEP_ROOT_BUDGET_MIN_TICKS: u64 = 200_000_000;
const SWEEP_ROOT_BUDGET_MAX_TICKS: u64 = 2_000_000_000;
/// Default adoption threshold: found facts must be >= this per mille of the seeds
/// actually SWEPT during the probe prefix (yield per swept environment — the same
/// basis as kissat's sweep delay governor). Measured calibration (2026-07-27):
/// goldcrest probes at ~45 per mille; barren cells at 0.
const SWEEP_ROOT_MIN_YIELD_PERMILLE: u64 = 20;
/// Probe prefix: the adoption decision is taken after this many swept environments
/// (or after 10% of the tick budget, whichever first), so a rejecting formula pays
/// only the bounded probe cost, never the full sweep budget.
const SWEEP_ROOT_PROBE_ENVS: u64 = 2_000;
/// Formulas above this live-variable count skip the root sweep entirely (wall + memory
/// guard, same shape as SAT_GATE_BVE_SCOPED_MAX_VARS). 400k keeps goldcrest (321k
/// live) in scope while excluding the vex/pj2008/g2 giants.
const SWEEP_ROOT_MAX_VARS: usize = 400_000;
/// Consecutive zero-yield COMPLETED root-sweep passes before the loop stops.
const SWEEP_ROOT_MAX_UNPRODUCTIVE_PASSES: u32 = 2;
/// Hard cap on root-sweep passes (safety backstop; the tick budget is the real limit).
const SWEEP_ROOT_MAX_PASSES: u32 = 64;
/// Skip SAT sweeping when phase search has already found a near-complete
/// SAT-looking assignment prefix. This protects long SAT trajectories where
/// true local equivalences can still derail a nearly complete model.
/// All-or-nothing congruence edit threshold: a `try_congruence` call first dry-runs
/// gate extraction + merge matching on the UNTOUCHED formula and applies nothing —
/// no hidden binaries, no ELS substitution, no merge equivalences — unless at least
/// this many merges are found. The 2026-07-11 medium A/B showed why: formulas below
/// this line (Timetables: 34k hidden binaries / 0 merges; Kakuro: pure-binary ELS
/// rewrites / 0 merges; oddball/QG7/Pancake: <50 merges) got their formulas rewritten
/// for zero congruence payoff and lost solved cells or blew up conflicts, while the
/// real winners (VexRiscv 7.7k, ibm 25k, oski 56k dry merges) sit far above it. The
/// 3000 line places every measured SAT-cell loser (bp5_CSO 1.9k, DLTM 3.0k,
/// bp4_BC012 1.0-1.1k, bp4_CSO_IXA 0.65k) on the no-edit side while keeping the
/// heavy gate circuits. Sub-threshold formulas stay byte-identical.
const CONGRUENCE_MIN_APPLY_MERGES: usize = 3000;
/// Skip congruence entirely (even the dry run) above this live-clause count: gate
/// extraction hashes every clause, which costs minutes on 20M+-clause formulas
/// (Kakuro: 165s) that show no gate structure anyway.
const CONGRUENCE_DRY_MAX_CLAUSES: usize = 10_000_000;

/// Root-congruence merge count at or above which a formula is treated as a
/// congruence-productive gate circuit (miter/BMC shape). On these formulas kissat's
/// win mechanism is interleaving congruence/substitution/elimination with search many
/// times (its probe/eliminate limits start small and grow NLOGN), while our flat
/// 1M-conflict inprocessing cadence yields only 2-3 rounds per 1800s. Productive
/// formulas therefore switch to the early doubling cadence below and run mid-search
/// elimination rounds; everything else keeps the shipped flat cadence untouched.
const CONGRUENCE_PRODUCTIVE_MIN_MERGES: u64 = 1000;
/// First inprocessing interval (conflicts) on congruence-productive formulas. The
/// interval doubles every round until it reaches the regular flat interval.
const INPROCESS_AGGRESSIVE_FIRST_INTERVAL: u64 = 10_000;
/// Kissat-analog `chronolevels` cap applied ONLY on congruence-productive formulas
/// (env override SAT_CHRONO_PRODUCTIVE_DELTA; 0 disables the gate). Kissat backtracks
/// chronologically whenever a backjump would discard more than chronolevels=100 levels
/// (learn.c backjump_limit); our global default SAT_CHRONO_MAX_DELTA=5000 nearly never
/// fires on deep-trail BMC/miter cells. Measured on VexRiscv (240s, same host): base
/// 767 decisions/conflict at avg backjump ~2000 levels vs kissat 35 decisions/conflict
/// — identical decision throughput, 22x conflict-density gap. Delta calibration
/// (standalone, 2026-07-12): 100 solves VexRiscv fastest (~1000s) but derails the
/// armed SAT cell ibm-2004 (390k -> 1.34M conflicts); 1000 keeps VexRiscv solvable
/// standalone (1578s, 3.09M conflicts) AND improves ibm-2004 (390k -> 292k conflicts,
/// -25%) because it fires only on catastrophic multi-thousand-level jumps (453 fires
/// on ibm vs 13k at delta=100). Applying delta=100 globally was measured-rejected
/// (2026-06-20, derails fragile SAT cells oddball/bp4), hence the root-productivity
/// gate. delta=1000 was promoted at 689f080 (A/B 2026-07-12-10-48-37). Re-calibrated
/// to 100 with the armed collapse bundle (worklist congruence + armed BVE bounds +
/// extended gate BVE + armed vivify, 2026-07-13): the mid-search collapse (ibm-2004
/// reaches 145k merges vs 20k) tames the delta=100 derailment that killed the
/// original parity attempt — ibm-2004 SAT 133s/370k conflicts at bundle+100 vs
/// 250s/981k at bundle+1000 vs 416s/292k baseline. Promotion A/B
/// log/abtest-cand-vs-base-2026-07-13-20-23-49: 64==64 solved, both-solved conflicts
/// 53,406,201 vs 53,455,304, PAR-2 149,169.6 vs 149,607.4, gate PASS.
const CHRONO_PRODUCTIVE_DELTA: usize = 100;
/// Root-BVE elimination yield (percent of declared variables) at or above which a
/// formula arms the aggressive inprocessing cadence even without congruence merges
/// (env override SAT_ELIM_PRODUCTIVE_MIN_PCT; 0 disables). Kissat's win mechanism on
/// structured-SAT cells (Timetable family: 41s, 170k conflicts) is mid-search
/// elimination — 67% of variables across 4 elimination rounds between search phases —
/// while our flat 1M-conflict cadence runs zero inprocess rounds in the first 300s and
/// never re-eliminates. Root elimination yield is the productivity dry-run for this
/// class: Timetable eliminates 50% and VexRiscv 58% at the root, so further rounds are
/// evidence-backed; formulas whose root yield is low keep the shipped flat cadence and
/// byte-identical trajectories.
const ELIM_PRODUCTIVE_MIN_PCT: usize = 0;

const SWEEP_SKIP_BEST_PHASE_PERMILLE: usize = 950;
const SWEEP_SKIP_TARGET_PHASE_PERMILLE: usize = 875;
const OTFS_MAX_LEARNED_LEN: usize = 20;
const OTFS_MAX_EXTRA_LITS: usize = 4;
const OTFS_RECENT_LEARNED_LIMIT: usize = 4;
/// Max participating reasons tracked per conflict for OTSS subsumption. Conflict
/// analysis can walk an unbounded chain; capping here keeps the post-analyze
/// candidate scan bounded. Sized to match OTFS recent-learned window scale.
const OTSS_MAX_PARTICIPATING_REASONS: usize = 16;
/// Max learned-clause length OTSS considers for the subset check, mirroring OTFS.
const OTSS_MAX_LEARNED_LEN: usize = 20;
/// Max extra literals a candidate reason can have beyond the learned-clause length.
/// Beyond this gap, the subset check is unlikely to succeed in practice and the
/// O(learned * reason) lit scan becomes wasteful.
const OTSS_MAX_EXTRA_LITS: usize = 6;
const INLINE_ABSTRACTION_CLAUSE_THRESHOLD: usize = 750_000;
const LAZY_DETACH_SMALL_CLAUSE_THRESHOLD: usize = 50_000;
const SORTED_SUBSUMPTION_MIN_LEN: usize = 2;
const TIER1_MAX_GLUE: u16 = 2;
const TIER2_MAX_GLUE: u16 = 6;
const TIER1_RELATIVE_NUMERATOR: u64 = 1;
const TIER1_RELATIVE_DENOMINATOR: u64 = 2;
const TIER2_RELATIVE_NUMERATOR: u64 = 9;
const TIER2_RELATIVE_DENOMINATOR: u64 = 10;
const MAX_USED_RECENTLY: u8 = 3;
/// kissat clause.h MAX_USED (5-bit `used` counter): under the fraction reduce
/// law a use sets the counter to 31 and every reduce decrements it by one, so a
/// tier1 clause survives 31 reductions after its last use and a tier2 clause is
/// protected only while `used >= 30` (used since the previous reduce).
const REDUCE_FRACTION_MAX_USED: u8 = 31;
const LEARNED_LIT_BUDGET_BASE: usize = 2_000;
const LEARNED_LIT_BUDGET_FACTOR: usize = 300;
const LBD_HARD_LEARNED_LIT_BUDGET_FACTOR: usize = 64;
const LBD_HARD_LEARNED_LIT_FORMULA_FACTOR: usize = 64;
const EMERGENCY_TIER1_MIN_AGE_CONFLICTS: u64 = 1_000;
const RESTART_FAST_ALPHA: f64 = 1.0 / 32.0;
#[cfg(test)]
const RESTART_SLOW_ALPHA: f64 = 1.0 / 4_096.0;
const KISSAT_EMA_RESTART_MIN_CONFLICTS: u64 = 50;
const KISSAT_EMA_RESTART_MARGIN: f64 = 1.20;
const RELUCTANT_RESTART_INTERVAL: u64 = 1 << 10;
const GC_GARBAGE_RATIO_NUMERATOR: usize = 1;
const GC_GARBAGE_RATIO_DENOMINATOR: usize = 3;
const GC_WATCHER_STALE_MIN: usize = 1_024;
/// Skip routine (non-emergency) copy-GC once the arena reaches this many words: on giant
/// formulas the GC's relocation map + new arena are a multi-GB transient that OOM-kills
/// instances which otherwise fit under `ulimit -v`. ~10-100x any normal medium arena.
const GC_SKIP_ARENA_WORDS: usize = 100_000_000;
const GC_WATCHER_STALE_RATIO_NUMERATOR: usize = 1;
const GC_WATCHER_STALE_RATIO_DENOMINATOR: usize = 10;
const VMTF_SINGLE_CONFLICT_BUDGET: u64 = 200_000;
const VMTF_SINGLE_DECISION_BUDGET: u64 = 500_000;
const VMTF_SINGLE_PROPAGATION_BUDGET: u64 = 200_000_000;
const VMTF_SINGLE_BEST_PHASE_MIN_VARS: usize = 10_000;
const VMTF_SINGLE_BEST_PHASE_MAX_VARS: usize = 100_000;
const VMTF_SINGLE_BEST_PHASE_MAX_CLAUSES: usize = 1_000_000;
const RANDOM_DECISION_INIT_CONFLICTS: u64 = 500;
const RANDOM_DECISION_INTERVAL_CONFLICTS: u64 = 500;
const RANDOM_DECISION_LENGTH_CONFLICTS: u64 = 10;
const RANDOM_DECISION_SEED: u64 = 0x9e37_79b9_7f4a_7c15;
const FORMULA_SMALL_CLAUSES: u64 = 10_000;
const FORMULA_MEDIUM_CLAUSES: u64 = 1_000_000;
const KISSAT_SMALL_CLAUSES: u64 = 100_000;
const KISSAT_BIGBIG_BINARY_FRACTION: f64 = 0.990;

type ClauseRef = usize;

const NO_CLAUSE_REF: ClauseRef = usize::MAX;
/// Compact relocation-map entry type for garbage collection. The GC relocation map is sized
/// to `arena.len()` (one entry per arena word); as `usize` that is an 8-byte-per-word transient
/// (~2GB on giant formulas, e.g. 00fd8ac ~256M words) that stacks on the live old arena + new
/// arena and trips the 16GB `ulimit -v` cap. Arena word indices are bounded by `arena.len()`,
/// which for any formula fitting a 16GB u32-word arena is < 4.0e9 < `u32::MAX` (4.29e9), so a
/// `u32` map is sound and halves the transient. `NO_RELOC` is the "clause not copied" sentinel.
type RelocRef = u32;
const NO_RELOC: RelocRef = u32::MAX;

/// Old->new clause-offset mapping used while rewriting references after GC compaction.
/// `Dense` is the classic arena-length relocation map. `Sparse` avoids that transient
/// allocation (4 bytes x arena.len(), ~1.7GB on OOM-giant instances) on the in-place
/// compaction path: `ids` holds the live old clause offsets in ascending order and
/// `new_off[k]` the new offset of `ids[k]`; offsets absent from `ids` (deleted clauses)
/// map to NO_RELOC exactly like the dense map.
enum RelocLookup<'a> {
    Dense(&'a [RelocRef]),
    Sparse {
        ids: &'a [u32],
        new_off: &'a [RelocRef],
    },
}

impl RelocLookup<'_> {
    #[inline]
    fn get(&self, old_idx: usize) -> RelocRef {
        match self {
            RelocLookup::Dense(map) => map.get(old_idx).copied().unwrap_or(NO_RELOC),
            RelocLookup::Sparse { ids, new_off } => {
                let Ok(old_idx) = u32::try_from(old_idx) else {
                    return NO_RELOC;
                };
                match ids.binary_search(&old_idx) {
                    Ok(k) => new_off[k],
                    Err(_) => NO_RELOC,
                }
            }
        }
    }
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
enum FormulaSizeClass {
    #[default]
    Unknown,
    Small,
    Medium,
    Large,
}

impl FormulaSizeClass {
    fn as_str(self) -> &'static str {
        match self {
            Self::Unknown => "unknown",
            Self::Small => "small",
            Self::Medium => "medium",
            Self::Large => "large",
        }
    }
}

#[derive(Clone, Copy, Debug, Default, PartialEq)]
struct FormulaClass {
    size_class: FormulaSizeClass,
    kissat_small: bool,
    kissat_bigbig: bool,
    binary_fraction: f64,
    avg_clause_size: f64,
    variable_density: f64,
}

impl FormulaClass {
    fn from_counts(vars: u64, clauses: u64, literals: u64, binary_clauses: u64) -> Self {
        let size_class = if clauses < FORMULA_SMALL_CLAUSES {
            FormulaSizeClass::Small
        } else if clauses <= FORMULA_MEDIUM_CLAUSES {
            FormulaSizeClass::Medium
        } else {
            FormulaSizeClass::Large
        };
        let binary_fraction = if clauses == 0 {
            0.0
        } else {
            binary_clauses as f64 / clauses as f64
        };
        let avg_clause_size = if clauses == 0 {
            0.0
        } else {
            literals as f64 / clauses as f64
        };
        let variable_density = if vars == 0 {
            0.0
        } else {
            literals as f64 / vars as f64
        };
        let kissat_small = clauses <= KISSAT_SMALL_CLAUSES;
        let kissat_bigbig = !kissat_small && binary_fraction >= KISSAT_BIGBIG_BINARY_FRACTION;
        Self {
            size_class,
            kissat_small,
            kissat_bigbig,
            binary_fraction,
            avg_clause_size,
            variable_density,
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct BinaryClauseId(u32);

/// High bit of a `BinaryEdge::clause_id` marks the edge deleted. The binary hot
/// loop previously did a random load into the 48-byte `BinaryClause` record per
/// edge just to read its `deleted` flag; tagging the edge keeps the deleted
/// check inside the sequentially-scanned edge array. Ids stay well below 2^31
/// (one per binary clause), and edges carrying a live id are never tagged, so
/// ids that reach `Conflict::Binary`/`ReasonRef::Binary` are always untagged.
const BINARY_EDGE_DELETED_TAG: u32 = 1 << 31;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct BinaryEdge {
    implied: i32,
    clause_id: BinaryClauseId,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
