#[derive(Clone, Debug)]
#[allow(dead_code)]
enum BinaryImplications {
    Nested(Vec<Vec<BinaryEdge>>),
    Flat {
        edges: Vec<BinaryEdge>,
        offsets: Vec<u32>,
        dirty: bool,
    },
}

impl BinaryImplications {
    fn nested(lit_count: usize) -> Self {
        Self::Nested(vec![Vec::new(); lit_count])
    }

    fn lit_index(lit: i32) -> usize {
        lit_to_index(lit)
    }

    #[allow(dead_code)]
    fn edges_for(&self, lit: i32) -> &[BinaryEdge] {
        let idx = Self::lit_index(lit);
        match self {
            Self::Nested(edges) => edges.get(idx).map(Vec::as_slice).unwrap_or(&[]),
            Self::Flat { edges, offsets, .. } => {
                let Some(&start) = offsets.get(idx) else {
                    return &[];
                };
                let end = offsets.get(idx + 1).copied().unwrap_or(edges.len() as u32);
                &edges[start as usize..end as usize]
            }
        }
    }

    fn len_for(&self, lit: i32) -> usize {
        self.edges_for(lit).len()
    }

    fn edge_for(&self, lit: i32, idx: usize) -> BinaryEdge {
        self.edges_for(lit)[idx]
    }

    fn add_edge(&mut self, antecedent: i32, edge: BinaryEdge) {
        let idx = Self::lit_index(antecedent);
        match self {
            Self::Nested(edges) => {
                // Lean giant construction starts with no per-literal edge lists;
                // grow on demand so a binary-fast-path config stays correct.
                if idx >= edges.len() {
                    edges.resize(idx + 1, Vec::new());
                }
                edges[idx].push(edge);
            }
            Self::Flat {
                edges,
                offsets,
                dirty,
            } => {
                let insert_at = offsets
                    .get(idx + 1)
                    .copied()
                    .map(|offset| offset as usize)
                    .unwrap_or(edges.len());
                edges.insert(insert_at, edge);
                for offset in offsets.iter_mut().skip(idx + 1) {
                    *offset = offset.saturating_add(1);
                }
                *dirty = true;
            }
        }
    }

    fn mark_deleted(&mut self, _id: BinaryClauseId) {
        if let Self::Flat { dirty, .. } = self {
            *dirty = true;
        }
    }

    /// Set the deleted tag on every edge under `antecedent` whose clause id is
    /// `id`. Called from the two `BinaryClause::deleted = true` sites so the
    /// edge tag stays exactly in sync with the record flag the hot loop used
    /// to consult.
    fn tag_deleted_edges(&mut self, antecedent: i32, id: BinaryClauseId) {
        let idx = Self::lit_index(antecedent);
        let list: &mut [BinaryEdge] = match self {
            Self::Nested(edges) => match edges.get_mut(idx) {
                Some(v) => v.as_mut_slice(),
                None => return,
            },
            Self::Flat { edges, offsets, .. } => {
                let Some(&start) = offsets.get(idx) else {
                    return;
                };
                let end = offsets.get(idx + 1).copied().unwrap_or(edges.len() as u32);
                &mut edges[start as usize..end as usize]
            }
        };
        for edge in list {
            if edge.clause_id.0 & !BINARY_EDGE_DELETED_TAG == id.0 {
                edge.clause_id.0 |= BINARY_EDGE_DELETED_TAG;
            }
        }
    }

    #[allow(dead_code)]
    fn rebuild_flat_if_needed(&mut self) {
        if let Self::Flat { dirty, .. } = self {
            *dirty = false;
        }
    }
}

