#[derive(Clone, Debug)]
struct MovingAverage {
    value: f64,
    initialized: bool,
    alpha: f64,
}

impl MovingAverage {
    fn new(alpha: f64) -> Self {
        Self {
            value: 0.0,
            initialized: false,
            alpha,
        }
    }

    fn update(&mut self, x: f64) {
        if !self.initialized {
            self.value = x;
            self.initialized = true;
        } else {
            self.value += self.alpha * (x - self.value);
        }
    }

    fn reset(&mut self) {
        self.value = 0.0;
        self.initialized = false;
    }
}

