    fn els_config() -> SolverConfig {
        SolverConfig {
            els: true,
            ..Default::default()
        }
    }

    #[test]
    fn els_substitutes_equivalent_literal_and_preserves_sat_model() {
        // 1 ≡ 2 via the binary pair (¬1∨2),(1∨¬2); the ternary clauses add no implication
        // edges, so the equivalence reaches ELS. ELS substitutes 2→1 and eliminates var 2,
        // and the reconstructed model must still satisfy every original clause.
        let cfg = els_config();
        let original = vec![vec![-1, 2], vec![1, -2], vec![1, 3, 4], vec![-2, -3, 5]];
        let mut s = make_solver_with_config(5, original.clone(), &cfg);
        let mut proof = ProofLog::disabled();
        assert!(s.solve_with_proof(&mut proof, &cfg), "instance is SAT");
        assert!(
            s.stats.els_substituted_vars >= 1,
            "ELS must substitute an equivalent variable"
        );
        assert!(s.eliminated[2], "substituted variable 2 must be marked eliminated");
        for clause in &original {
            assert!(
                clause.iter().any(|&lit| s.lit_value(lit) == TRUE),
                "reconstructed model must satisfy original clause {clause:?}"
            );
        }
    }

    #[test]
    fn els_detects_self_negation_unsat() {
        // A binary implication SCC containing both +1 and -1 (1 ≡ ¬1) ⇒ UNSAT, found by ELS.
        let cfg = els_config();
        let mut s = make_solver_with_config(
            2,
            vec![vec![-1, 2], vec![-2, -1], vec![1, -2], vec![2, 1]],
            &cfg,
        );
        let mut proof = ProofLog::disabled();
        assert!(s.enqueue_root_units());
        assert!(s.propagate().is_none());
        assert!(
            s.try_els(&mut proof),
            "ELS must prove UNSAT via the self-negation SCC"
        );
        assert!(s.has_empty_clause);
    }

    #[test]
    fn els_substitution_preserves_unsat() {
        // Equivalences 1≡2, 3≡4, 5≡6 plus an UNSAT core over {1,3,5} written partly via the
        // even equivalents, so ELS substitutes before search refutes the merged core.
        let cfg = els_config();
        let clauses = vec![
            vec![-1, 2],
            vec![1, -2],
            vec![-3, 4],
            vec![3, -4],
            vec![-5, 6],
            vec![5, -6],
            vec![1, 3, 5],
            vec![2, 4, -5],
            vec![2, -3, 6],
            vec![2, -3, -5],
            vec![-1, 4, 6],
            vec![-1, 4, -5],
            vec![-1, -3, 6],
            vec![-1, -3, -5],
        ];
        let mut s = make_solver_with_config(6, clauses, &cfg);
        let mut proof = ProofLog::disabled();
        assert!(
            !s.solve_with_proof(&mut proof, &cfg),
            "the substituted core is UNSAT"
        );
    }

    #[test]
    fn els_disabled_by_default_does_not_substitute() {
        let cfg = SolverConfig::default();
        assert!(!cfg.els);
        let mut s = make_solver_with_config(5, vec![vec![-1, 2], vec![1, -2], vec![1, 3, 4]], &cfg);
        let mut proof = ProofLog::disabled();
        let _ = s.solve_with_proof(&mut proof, &cfg);
        assert_eq!(
            s.stats.els_substituted_vars, 0,
            "the default path must never run ELS"
        );
    }

    fn congruence_config() -> SolverConfig {
        // Isolate congruence: no BVE/ELS so the merge and its substitution are observable.
        SolverConfig {
            congruence: true,
            simplification: false,
            els: false,
            ..Default::default()
        }
    }

    #[test]
    fn inprocess_round_runs_congruence_when_enabled() {
        // Two identical AND gates 3 = AND(1,2) and 4 = AND(1,2). An inprocessing round
        // with SAT_CONGRUENCE on must run the congruence closure mid-search: the outputs
        // merge and ELS substitutes variable 4 by representative 3.
        let cfg = SolverConfig {
            congruence: true,
            inprocess: true,
            vivify: false,
            simplification: false,
            els: false,
            ..Default::default()
        };
        let original = vec![
            vec![-3, 1],
            vec![-3, 2],
            vec![3, -1, -2],
            vec![-4, 1],
            vec![-4, 2],
            vec![4, -1, -2],
            vec![-3, 5],
            vec![-4, 6],
        ];
        let mut s = make_solver_with_config(6, original, &cfg);
        s.congruence_min_apply_merges = 1;
        s.sweep = false;
        let mut proof = ProofLog::disabled();
        assert!(s.inprocess_round(&mut proof, &cfg));
        assert!(
            s.stats.congruence_merges >= 1,
            "inprocess round must merge the two equivalent AND outputs, merges={}",
            s.stats.congruence_merges
        );
        assert!(s.eliminated[4], "variable 4 must be substituted away mid-search");
    }

    #[test]
    fn inprocess_round_aggressive_runs_midsearch_elimination() {
        // Aggressive (congruence-productive) inprocessing must run a mid-search BVE
        // round: variable 1 appears in two clauses resolvable to one resolvent, so the
        // round eliminates it and search still finishes with a model that satisfies
        // every original clause after extension replay.
        let cfg = SolverConfig {
            congruence: true,
            inprocess: true,
            vivify: false,
            els: false,
            ..Default::default()
        };
        let original = vec![vec![1, 2], vec![-1, 3], vec![2, 3, 4]];
        let mut s = make_solver_with_config(4, original.clone(), &cfg);
        s.sweep = false;
        s.inprocess_aggressive = true;
        let mut proof = ProofLog::disabled();
        assert!(s.inprocess_round(&mut proof, &cfg));
        assert!(
            s.stats.preprocess_eliminated_vars >= 1,
            "aggressive round must run mid-search BVE, eliminated={}",
            s.stats.preprocess_eliminated_vars
        );
        assert!(
            !s.use_simplification,
            "eliminate(true) turn-off must restore the umbrella flag"
        );
        assert!(s.solve(), "instance is SAT");
        for clause in &original {
            assert!(
                clause.iter().any(|&lit| s.lit_value(lit) == TRUE),
                "reconstructed model must satisfy original clause {clause:?}"
            );
        }
    }

    #[test]
    fn inprocess_factor_introduces_fresh_vars_and_preserves_sat_model() {
        // 6x6 product grid: clauses (f_i ∨ d_j) for f in vars 1..6, d in vars 7..12.
        // Factoring replaces the 36 products with 12 clauses over a fresh variable
        // (clause reduction 24 > FACTOR_BOUND=16). The armed round must apply it
        // mid-search, grow the variable-indexed state, and still produce a model
        // satisfying every original clause.
        let cfg = SolverConfig {
            inprocess: true,
            congruence: false,
            vivify: false,
            els: false,
            probe: false,
            ..Default::default()
        };
        let mut original: Vec<Vec<i32>> = Vec::new();
        for f in 1..=6 {
            for d in 7..=12 {
                original.push(vec![f, d]);
            }
        }
        let mut s = make_solver_with_config(12, original.clone(), &cfg);
        s.sweep = false;
        s.use_elim = false;
        s.inprocess_aggressive = true;
        s.factor_inprocess = true;
        let mut proof = ProofLog::disabled();
        assert!(s.inprocess_round(&mut proof, &cfg));
        assert!(
            s.stats.factor_inprocess_fresh_vars >= 1,
            "armed round must factor the product grid, fresh_vars={}",
            s.stats.factor_inprocess_fresh_vars
        );
        assert!(
            s.assignment.len() > 13,
            "variable-indexed state must have grown, len={}",
            s.assignment.len()
        );
        assert!(s.solve(), "instance is SAT");
        for clause in &original {
            assert!(
                clause.iter().any(|&lit| s.lit_value(lit) == TRUE),
                "model must satisfy original clause {clause:?}"
            );
        }
    }

