    /// 3-input XOR clause family `v1 ⊕ v2 ⊕ v3 ⊕ out = 0` (the 8 length-4 clauses with an odd
    /// number of negations). These are not ITE- or AND-extractable, so they isolate the XOR
    /// gate path.
    fn xor3_gate_clauses(v1: i32, v2: i32, v3: i32, out: i32) -> Vec<Vec<i32>> {
        let vars = [v1, v2, v3, out];
        let mut clauses = Vec::new();
        for s in 0u32..16 {
            if s.count_ones() & 1 == 1 {
                let clause = vars
                    .iter()
                    .enumerate()
                    .map(|(i, &v)| if (s >> i) & 1 == 1 { -v } else { v })
                    .collect();
                clauses.push(clause);
            }
        }
        clauses
    }

    #[test]
    fn congruence_merges_equivalent_xor_gate_outputs_and_preserves_model() {
        // 4 = XOR(1,2,3) and 5 = XOR(1,2,3) ⇒ 4 ≡ 5; congruence (with SAT_CONGRUENCE_XOR)
        // merges them via the parity resolution ladder and ELS eliminates variable 5 (rep 4).
        let cfg = SolverConfig {
            congruence: true,
            congruence_xor: true,
            simplification: false,
            els: false,
            gauss: false,
            ..Default::default()
        };
        let mut original = xor3_gate_clauses(1, 2, 3, 4);
        original.extend(xor3_gate_clauses(1, 2, 3, 5));
        original.push(vec![-4, 6]); // keep 4 live outside its gate
        original.push(vec![-5, 7]); // keep 5 live outside its gate
        let mut s = make_solver_with_config(7, original.clone(), &cfg);
        s.congruence_min_apply_merges = 1;
        let mut proof = ProofLog::disabled();
        assert!(s.solve_with_proof(&mut proof, &cfg), "instance is SAT");
        assert!(
            s.stats.congruence_merges >= 1,
            "congruence must merge the two equivalent XOR outputs"
        );
        assert!(s.eliminated[5], "variable 5 must be substituted away");
        for clause in &original {
            assert!(
                clause.iter().any(|&lit| s.lit_value(lit) == TRUE),
                "reconstructed model must satisfy original clause {clause:?}"
            );
        }
    }

    #[test]
    fn congruence_worklist_cascades_layered_gates_and_preserves_model() {
        // Layer 1: 3 = AND(1,2), 4 = AND(1,2) ⇒ 3 ≡ 4. Layer 2: 6 = AND(3,5),
        // 7 = AND(4,5) — congruent only through the layer-1 merge. With the worklist
        // closure both merges land in one try_congruence round; ELS must substitute
        // away both duplicates and the reconstructed model must satisfy every
        // original clause.
        let cfg = congruence_config();
        let original = vec![
            vec![-3, 1],
            vec![-3, 2],
            vec![3, -1, -2],
            vec![-4, 1],
            vec![-4, 2],
            vec![4, -1, -2],
            vec![-6, 3],
            vec![-6, 5],
            vec![6, -3, -5],
            vec![-7, 4],
            vec![-7, 5],
            vec![7, -4, -5],
            vec![-6, 8],
            vec![-7, 9],
        ];
        let mut s = make_solver_with_config(9, original.clone(), &cfg);
        s.congruence_min_apply_merges = 1;
        s.congruence_worklist = true;
        let mut proof = ProofLog::disabled();
        assert!(s.solve_with_proof(&mut proof, &cfg), "instance is SAT");
        assert!(
            s.stats.congruence_merges >= 2,
            "worklist closure must cascade to the layer-2 merge (got {})",
            s.stats.congruence_merges
        );
        assert!(s.eliminated[4], "variable 4 must be substituted away");
        assert!(s.eliminated[7], "variable 7 must be substituted away");
        for clause in &original {
            assert!(
                clause.iter().any(|&lit| s.lit_value(lit) == TRUE),
                "reconstructed model must satisfy original clause {clause:?}"
            );
        }
    }

    #[test]
    fn congruence_worklist_proves_cascaded_self_negation_unsat() {
        // Layer 1 merges 3 ≡ 4; layer 2 then yields 6 = AND(3,5) versus ¬6 = AND(4,5),
        // i.e. 6 ≡ ¬6 — reachable only through the cascade. The worklist path must
        // prove UNSAT with the refutation emitted AFTER the supporting merge binaries.
        let cfg = congruence_config();
        let original = vec![
            vec![-3, 1],
            vec![-3, 2],
            vec![3, -1, -2],
            vec![-4, 1],
            vec![-4, 2],
            vec![4, -1, -2],
            vec![-6, 3],
            vec![-6, 5],
            vec![6, -3, -5],
            vec![6, 4],
            vec![6, 5],
            vec![-6, -4, -5],
        ];
        let mut s = make_solver_with_config(6, original, &cfg);
        s.congruence_min_apply_merges = 1;
        s.congruence_worklist = true;
        let mut proof = ProofLog::disabled();
        assert!(
            !s.solve_with_proof(&mut proof, &cfg),
            "cascaded self-negation must be UNSAT"
        );
    }

    #[test]
    fn congruence_armed_threshold_applies_only_when_armed() {
        // Two equivalent AND gates -> exactly 1 merge, far below the shipped 3000
        // threshold. With the armed threshold at 1: an UNARMED solver must leave the
        // formula untouched (dry-run gate holds); once inprocess_aggressive is armed
        // the same closure applies the merge.
        let cfg = congruence_config();
        let original = vec![
            vec![-3, 1],
            vec![-3, 2],
            vec![3, -1, -2],
            vec![-4, 1],
            vec![-4, 2],
            vec![4, -1, -2],
            vec![-3, 5],
            vec![-4, 6],
        ];
        let mut proof = ProofLog::disabled();

        let mut unarmed = make_solver_with_config(6, original.clone(), &cfg);
        unarmed.congruence_armed_min_merges = 1;
        assert!(unarmed.enqueue_root_units());
        assert!(unarmed.propagate().is_none());
        assert!(!unarmed.try_congruence(&mut proof, false));
        assert_eq!(
            unarmed.stats.congruence_merges, 0,
            "unarmed solver keeps the shipped threshold"
        );

        let mut armed = make_solver_with_config(6, original, &cfg);
        armed.congruence_armed_min_merges = 1;
        armed.inprocess_aggressive = true;
        assert!(armed.enqueue_root_units());
        assert!(armed.propagate().is_none());
        armed.try_congruence(&mut proof, false);
        assert!(
            armed.stats.congruence_merges >= 1,
            "armed solver applies sub-threshold merges at the armed threshold"
        );
    }

