    #[test]
    fn test_bve_proof_deletes_source_clauses_after_resolvents() {
        // Regression for the BVE DRAT-proof ordering bug: the proof deletions of the
        // eliminated source clauses must be emitted *after* the resolvent additions.
        // Emitting deletions first strips the RAT support for the resolvents, and
        // drat-trim rejects the proof with "RAT check failed on all possible pivots".
        let config = SolverConfig {
            eliminate_occurrence_limit: 0,
            full_bsr: false,
            ..SolverConfig::default()
        };
        // var 1: pos in (1,2),(1,3); neg in (-1,4),(-1,5). occlim=0 -> var 1 is eliminated,
        // producing resolvents (2,4),(2,5),(3,4),(3,5). vars 2..=5 frozen so they survive.
        let mut s = Solver::new_with_config(
            5,
            vec![vec![1, 2], vec![1, 3], vec![-1, 4], vec![-1, 5]],
            &config,
        );
        s.frozen[2] = true;
        s.frozen[3] = true;
        s.frozen[4] = true;
        s.frozen[5] = true;

        let dir = make_temp_dir("bve-proof-order");
        let mut proof = ProofLog::new(&dir, 64, false);
        assert!(s.eliminate(false, &mut proof));
        assert!(s.eliminated[1], "var 1 must be eliminated under occlim=0");
        proof.finish_unsat();

        let proof_text =
            fs::read_to_string(dir.join("proof.out")).expect("failed to read BVE proof");
        let line_idx = |needle: &str| proof_text.lines().position(|l| l == needle);
        // A resolvent addition (e.g. "2 4 0") must precede every deletion of an eliminated
        // source clause (e.g. "d 1 2 0").
        let resolvent_add =
            line_idx("2 4 0").expect("resolvent (2,4) must be added to the proof");
        for del in ["d 1 2 0", "d 1 3 0", "d -1 4 0", "d -1 5 0"] {
            let del_idx =
                line_idx(del).unwrap_or_else(|| panic!("missing source-clause deletion {del}"));
            assert!(
                resolvent_add < del_idx,
                "resolvent add (line {resolvent_add}) must precede source deletion {del} \
                 (line {del_idx}); deletions must come after resolvents in the DRAT proof\n\
                 proof:\n{proof_text}"
            );
        }
    }

    fn make_temp_dir(label: &str) -> PathBuf {
        let nanos = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .expect("time went backwards")
            .as_nanos();
        let path = std::env::temp_dir().join(format!(
            "sat-playground-{label}-{}-{nanos}",
            std::process::id()
        ));
        fs::create_dir_all(&path).expect("failed to create temp dir");
        path
    }

    fn decision_prefix(mut solver: Solver, limit: usize) -> Vec<i32> {
        let mut prefix = Vec::new();
        for _ in 0..limit {
            let Some(lit) = solver.pick_branch_lit() else {
                break;
            };
            prefix.push(lit);
            solver.decide(lit);
        }
        prefix
    }

    #[test]
    fn memory_preflight_accounts_for_dense_watchers() {
        let clauses = vec![vec![1, 2], vec![-1, 3]];
        let estimated = solver_construction_extra_bytes(10, &clauses, None);
        let watcher_headers = bytes_for_elems(20, std::mem::size_of::<Vec<Watcher>>());

        assert!(estimated >= watcher_headers);
    }

    #[test]
    fn memory_preflight_trips_before_dense_allocation_exceeds_limit() {
        let clauses = vec![vec![1, -2, 3]; 100];
        let extra = solver_construction_extra_bytes(10_000, &clauses, None);
        let current = 64 * 1024 * 1024;
        let limit = current + extra;

        let preflight = memory_preflight_with_limit(10_000, &clauses, limit, current, None)
            .expect("90% threshold should trip before allocation reaches the cap");

        assert_eq!(preflight.limit_bytes, limit);
        assert!(preflight.estimated_peak_bytes >= preflight.threshold_bytes);
    }

    #[test]
    fn memory_preflight_skips_simplification_transients_when_disabled() {
        // Giant-light formulas (simplification off) never allocate the occurrence
        // entries or the inline-abstraction migration transient; the estimate must
        // not charge them (83aa: the stale charge was ~4GB of a 14.7GB estimate
        // against a 12.7GB measured true peak).
        let clauses = vec![vec![1, -2, 3]; INLINE_ABSTRACTION_CLAUSE_THRESHOLD];
        let with_simp = solver_construction_extra_bytes(10_000, &clauses, Some(true));
        let without_simp = solver_construction_extra_bytes(10_000, &clauses, Some(false));
        let lits = initial_lit_count(&clauses);
        let literal_slots = lits + clauses.len() as u64;
        let expected_delta = bytes_for_elems(lits, std::mem::size_of::<u32>())
            + bytes_for_elems(literal_slots, std::mem::size_of::<RelocRef>())
            + bytes_for_elems(
                literal_slots + clauses.len() as u64,
                std::mem::size_of::<u32>(),
            );
        assert_eq!(with_simp - without_simp, expected_delta);
    }

    #[test]
    fn memory_preflight_allows_small_instance_under_limit() {
        let clauses = vec![vec![1, -2, 3]; 10];
        let limit = 1024 * 1024 * 1024;

        assert!(memory_preflight_with_limit(10, &clauses, limit, 0, None).is_none());
    }

    fn write_cnf_file(label: &str, content: &str) -> PathBuf {
        let dir = make_temp_dir(label);
        let path = dir.join("formula.cnf");
        fs::write(&path, content).expect("failed to write test cnf");
        path
    }

    #[test]
    fn giant_arena_parse_matches_nested_parse() {
        let content = "c comment line\n\np cnf 5 6\n1 2 0\n-1 3 4 0\n5 0\n-2 -3\n-4 0\n0\n1 -5 0\n";
        let path = write_cnf_file("giant-parse-eq", content);
        let path = path.to_str().unwrap();
        let (nested_vars, nested) = parse_cnf(path).expect("nested parse");
        let (giant_vars, pre) = parse_cnf_giant_arena(path).expect("giant parse");
        assert_eq!(nested_vars, giant_vars);
        assert_eq!(pre.clause_ids.len(), nested.len());
        assert_eq!(pre.total_lits, initial_lit_count(&nested));
        assert_eq!(ParsedFormula::GiantArena(pre).into_nested(), nested);
    }

    #[test]
    fn giant_arena_parse_error_messages_match_nested() {
        for content in [
            "p cnf 2 1\n1 3 0\n",
            "p cnf 2 1\n1 x 0\n",
            "p cnf 2 1\n1 2\n",
            "1 2 0\n",
            "p cnf 2 1\np cnf 2 1\n1 0\n",
            "c only comments\n",
            "p cnf x 1\n1 0\n",
        ] {
            let path = write_cnf_file("giant-parse-err", content);
            let path = path.to_str().unwrap();
            let nested_err = parse_cnf(path).expect_err("nested parse should fail");
            let giant_err = parse_cnf_giant_arena(path).expect_err("giant parse should fail");
            assert_eq!(nested_err, giant_err);
        }
    }

    #[test]
    fn giant_arena_solver_matches_nested_solver() {
        // A giant-light-style config (raw clause order, no simplification) over a
        // formula mixing units, binaries, and long clauses: the lean giant-arena
        // construction must reproduce the nested construction's solve exactly.
        let content = "p cnf 6 7\n1 2 0\n-1 3 4 0\n-2 -3 0\n5 0\n-5 -4 2 0\n1 -3 -4 5 0\n-6 1 0\n";
        let path = write_cnf_file("giant-solver-eq", content);
        let path = path.to_str().unwrap();
        let mut config = SolverConfig::default();
        apply_giant_light_profile(&mut config);

        let (num_vars, nested) = parse_cnf(path).expect("nested parse");
        let (_, pre) = parse_cnf_giant_arena(path).expect("giant parse");

        let mut nested_solver =
            Solver::new_with_config_formula(num_vars, ParsedFormula::Nested(nested), &config);
        let mut giant_solver =
            Solver::new_with_config_formula(num_vars, ParsedFormula::GiantArena(pre), &config);

        assert_eq!(nested_solver.arena, giant_solver.arena);
        assert_eq!(
            nested_solver.original_clause_ids,
            giant_solver.original_clause_ids
        );
        assert_eq!(nested_solver.original_literals, giant_solver.original_literals);
        assert_eq!(nested_solver.watch_lists_len(), giant_solver.watch_lists_len());
        for wl_idx in 0..nested_solver.watch_lists_len() {
            assert_eq!(
                nested_solver.watch_list(wl_idx),
                giant_solver.watch_list(wl_idx),
                "watch list {wl_idx} differs"
            );
        }
        assert_eq!(nested_solver.root_unit_clauses, giant_solver.root_unit_clauses);

        // Lean giant construction skips the simplification-only side structures.
        assert!(giant_solver.occurs.is_empty());
        assert!(giant_solver.n_occ.is_empty());
        assert!(giant_solver.occurs_dirty.is_empty());
        assert!(giant_solver.lbd_seen.is_empty());
        assert_eq!(giant_solver.binary_implications.len_for(1), 0);

        let nested_result = nested_solver.solve();
        let giant_result = giant_solver.solve();
        assert_eq!(nested_result, giant_result);
        assert_eq!(nested_solver.stats.conflicts, giant_solver.stats.conflicts);
        assert_eq!(
            nested_solver.stats.propagations,
            giant_solver.stats.propagations
        );
        assert_eq!(nested_solver.assignment, giant_solver.assignment);
    }

    #[test]
    fn giant_arena_estimate_below_nested_estimate() {
        let vars = 25_000_000usize;
        let clause_count = 60_000_000u64;
        let lits = 140_000_000u64;
        let giant =
            solver_construction_extra_bytes_counts(vars, clause_count, lits, Some(false), true);
        let nested =
            solver_construction_extra_bytes_counts(vars, clause_count, lits, Some(false), false);
        assert!(giant < nested);
        // The giant estimate must at least stop charging the resident arena words and
        // the occurs headers the lean constructor never allocates.
        let arena_words = bytes_for_elems(
            lits.saturating_add(clause_count),
            std::mem::size_of::<u32>(),
        );
        let occurs_headers =
            bytes_for_elems(vars as u64 + 1, std::mem::size_of::<Vec<u32>>());
        assert!(nested - giant >= arena_words + occurs_headers);
    }

    #[test]
    fn streaming_model_verify_matches_clause_semantics() {
        let path = write_cnf_file("verify-stream", "p cnf 3 2\n1 -2 0\n2 3 0\n");
        let path_str = path.to_str().unwrap();
        let mut model = vec![UNASSIGNED; 4];
        model[1] = TRUE;
        model[2] = FALSE;
        model[3] = TRUE;
        assert!(verify_model_against_cnf_path(path_str, &model));
        model[3] = FALSE;
        assert!(!verify_model_against_cnf_path(path_str, &model));

        let empty_clause = write_cnf_file("verify-empty-clause", "p cnf 2 2\n1 0\n0\n");
        assert!(!verify_model_against_cnf_path(
            empty_clause.to_str().unwrap(),
            &[UNASSIGNED, TRUE, TRUE]
        ));

        let malformed = write_cnf_file("verify-malformed", "p cnf 2 1\n1 2\n");
        assert!(!verify_model_against_cnf_path(
            malformed.to_str().unwrap(),
            &[UNASSIGNED, TRUE, TRUE]
        ));

        let no_problem_line = write_cnf_file("verify-no-pline", "c nothing\n");
        assert!(!verify_model_against_cnf_path(
            no_problem_line.to_str().unwrap(),
            &[UNASSIGNED]
        ));
    }

    fn watched_literals(s: &Solver, clause_idx: usize) -> Option<(i32, i32)> {
        if s.clause_len(clause_idx) < 2 {
            return None;
        }
        Some((s.clause_lit(clause_idx, 0), s.clause_lit(clause_idx, 1)))
    }

    fn live_original_clauses(s: &Solver) -> Vec<Vec<i32>> {
        let mut clauses: Vec<Vec<i32>> = s
            .original_clause_ids
            .iter()
            .map(|&clause_idx| clause_idx as usize)
            .filter(|&clause_idx| !s.clause_is_deleted(clause_idx))
            .map(|clause_idx| s.clause_slice(clause_idx).to_vec())
            .collect();
        clauses.sort();
        clauses
    }

    fn rewrite_clause_for_test(s: &mut Solver, clause_idx: usize, lits: &[i32]) {
        assert_eq!(s.clause_len(clause_idx), lits.len());
        for (lit_pos, &lit) in lits.iter().enumerate() {
            s.set_clause_lit(clause_idx, lit_pos, lit);
        }
    }

    fn install_manual_state(
        s: &mut Solver,
        trail: &[i32],
        trail_limits: &[usize],
        reason_overrides: &[(usize, usize)],
    ) {
        s.assignment.fill(UNASSIGNED);
        s.decision_level.fill(0);
        s.reason.fill(NO_REASON);
        s.trail.clear();
        s.trail.extend_from_slice(trail);
        s.trail_limits = trail_limits.to_vec();
        s.root_trail_len = 0;
        s.propagate_head = s.trail.len();

        let mut level = 0usize;
        let mut next_limit_idx = 0usize;
        for (trail_idx, &lit) in trail.iter().enumerate() {
            while next_limit_idx < trail_limits.len() && trail_limits[next_limit_idx] == trail_idx {
                level += 1;
                next_limit_idx += 1;
            }

            let var = lit.unsigned_abs() as usize;
            s.assignment[var] = if lit > 0 { TRUE } else { FALSE };
            s.decision_level[var] = level as u32;
        }

        for &(var, reason_idx) in reason_overrides {
            s.set_reason_ref(var, ReasonRef::Clause(reason_idx));
        }
    }

