        let not_subset = s.add_clause(vec![1, -2, 3]);
        s.otss_participating_reasons.push(not_subset);
        let mut proof_log = ProofLog::disabled();

        let deleted = s.otss_subsume_participating_reasons(&[1, 2], None, &mut proof_log);

