        assert_eq!(s.target_phase[2], FALSE);

        s.decide(1);
        s.decide(-2);
        s.decide(3);
        s.maybe_capture_phase_prefix();
        assert_eq!(s.target_assigned, 3);
        assert_eq!(s.target_phase[3], TRUE);
